    icon: "bell",
    action: "notification:read",
  },
  {
    key: "activity",
    label: "Activity",
    segment: "activity",
    icon: "history",
    action: "activity:read",
    flag: "activity_feed",
  },
  {
    key: "members",
    label: "Members",
    segment: "members",
    icon: "users",
    action: "member:read",
  },
];

export const SETTINGS_NAV: readonly NavItem[] = [
  {
    key: "settings.general",
    label: "General",
    segment: "general",
    action: "org:read",
  },
  {
    key: "settings.members",
    label: "Members",
    segment: "members",
    action: "member:read",
  },
  {
    key: "settings.billing",
    label: "Billing",
    segment: "billing",
    action: "org:manage_billing",
  },
  {
    key: "settings.flags",
