import { describe, expect, it } from "vitest";
import {
  activeFilterCount,
  issueFilterQueryString,
  issueFilterToParams,
  parseIssueFilterParams,
  UNASSIGNED_TOKEN,
} from "@/hooks/issue-filter-params";
import type { LabelId, ProjectId, UserId } from "@/types/common";
import type { IssueFilter } from "@/types/issue";

function params(query: string): URLSearchParams {
  return new URLSearchParams(query);
}

describe("issue-filter-params/parse", () => {
  it("returns an empty filter for an empty query string", () => {
    expect(parseIssueFilterParams(params(""))).toEqual({});
  });

  it("parses comma-separated statuses and drops unknown values", () => {
    const filter = parseIssueFilterParams(params("status=todo,nonsense,done"));
    expect(filter.status).toEqual(["todo", "done"]);
  });

  it("distinguishes unassigned from no assignee filter", () => {
    expect(parseIssueFilterParams(params("assignee=none")).assigneeId).toBeNull();
    expect("assigneeId" in parseIssueFilterParams(params(""))).toBe(false);
  });

  it("reads the archived flag only for the literal 1", () => {
    expect(parseIssueFilterParams(params("archived=1")).includeArchived).toBe(
      true,
    );
    expect(
      parseIssueFilterParams(params("archived=true")).includeArchived,
    ).toBeUndefined();
  });
});

describe("issue-filter-params/serialise", () => {
  const filter: IssueFilter = {
    projectId: "prj_1" as ProjectId,
    status: ["todo", "in_progress"],
    assigneeId: "usr_1" as UserId,
    labelIds: ["lbl_1" as LabelId, "lbl_2" as LabelId],
    query: "crash",
    includeArchived: true,
  };

  it("round-trips through the query string", () => {
    const restored = parseIssueFilterParams(
      params(new URLSearchParams(issueFilterToParams(filter)).toString()),
    );
    expect(restored).toEqual(filter);
  });

  it("omits empty dimensions entirely", () => {
    expect(issueFilterToParams({ status: [], labelIds: [], query: "" })).toEqual(
      {},
    );
  });

  it("writes unassigned as the sentinel token", () => {
    expect(issueFilterToParams({ assigneeId: null }).assignee).toBe(
      UNASSIGNED_TOKEN,
    );
  });

  it("produces a bare path for an empty filter", () => {
    expect(issueFilterQueryString({})).toBe("");
    expect(issueFilterQueryString({ query: "x" })).toBe("?q=x");
  });

  it("counts the narrowed dimensions", () => {
    expect(activeFilterCount({})).toBe(0);
    expect(activeFilterCount(filter)).toBe(6);
  });
});
/** `createIssueSchema` defaults, bounds and error paths. */
import { describe, expect, it } from "vitest";
import {
  archiveIssueSchema,
  assignIssueSchema,
  changeIssueStatusSchema,
  createIssueSchema,
  issueFilterSchema,
  moveIssueSchema,
  updateIssueSchema,
} from "@/schemas/issue";
import { ISSUE_PRIORITIES, ISSUE_STATUSES } from "@/types/issue";
import { ALICE, ORG_A } from "../helpers/factories";

const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP";
const ISSUE = "01HZZZSSSSSSSSSSSSSSSSSSSS";

function createInput(overrides: Record<string, unknown> = {}) {
  return { orgId: ORG_A, projectId: PROJECT, title: "Fix the link", ...overrides };
}

describe("schemas/issue", () => {
  it("applies every documented default", () => {
    expect(createIssueSchema.parse(createInput())).toMatchObject({
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  });

  it("accepts every status and priority in the domain", () => {
    for (const status of ISSUE_STATUSES) {
      expect(createIssueSchema.safeParse(createInput({ status })).success, status).toBe(
        true,
      );
    }
    for (const priority of ISSUE_PRIORITIES) {
      expect(
        createIssueSchema.safeParse(createInput({ priority })).success,
        priority,
      ).toBe(true);
    }
  });

  it("rejects a status outside the enum", () => {
    expect(createIssueSchema.safeParse(createInput({ status: "shipped" })).success).toBe(
      false,
    );
  });

  it("bounds the title at 3 and 200 characters, reporting the title path", () => {
    expect(createIssueSchema.safeParse(createInput({ title: "ab" })).success).toBe(false);
    expect(
      createIssueSchema.safeParse(createInput({ title: "a".repeat(201) })).success,
    ).toBe(false);

    const result = createIssueSchema.safeParse(createInput({ title: "ab" }));
    if (result.success) return;
    expect(result.error.issues[0]?.path).toEqual(["title"]);
    expect(result.error.issues[0]?.message).toBe("give the issue a title");
  });

  it("requires ULID ids and reports the offending path", () => {
    const result = createIssueSchema.safeParse(createInput({ projectId: "nope" }));
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.issues[0]?.path).toEqual(["projectId"]);
  });

  it("bounds the estimate to a whole number between 0 and 100", () => {
    expect(createIssueSchema.safeParse(createInput({ estimate: 8 })).success).toBe(true);
    expect(createIssueSchema.safeParse(createInput({ estimate: 1.5 })).success).toBe(
      false,
    );
    expect(createIssueSchema.safeParse(createInput({ estimate: 101 })).success).toBe(
      false,
    );
    expect(createIssueSchema.safeParse(createInput({ estimate: null })).success).toBe(
      true,
    );
  });

  it("caps the label list at 20", () => {
    const label = "01HZZZKKKKKKKKKKKKKKKKKKKK";
    expect(
      createIssueSchema.safeParse(createInput({ labelIds: Array(20).fill(label) }))
        .success,
    ).toBe(true);
    expect(
      createIssueSchema.safeParse(createInput({ labelIds: Array(21).fill(label) }))
        .success,
    ).toBe(false);
  });

  it("requires a real ISO datetime for dueAt", () => {
    expect(
      createIssueSchema.safeParse(createInput({ dueAt: "2026-03-15T12:00:00.000Z" }))
        .success,
    ).toBe(true);
    expect(createIssueSchema.safeParse(createInput({ dueAt: "2026-03-15" })).success).toBe(
      false,
    );
  });

  it("makes every updatable field optional on update", () => {
    expect(updateIssueSchema.parse({ orgId: ORG_A, issueId: ISSUE })).toEqual({
      orgId: ORG_A,
      issueId: ISSUE,
    });
  });

  it("still bounds fields that are present on update", () => {
    expect(
      updateIssueSchema.safeParse({ orgId: ORG_A, issueId: ISSUE, title: "ab" }).success,
    ).toBe(false);
  });

  it("requires a status on the status-change payload", () => {
    expect(
      changeIssueStatusSchema.safeParse({ orgId: ORG_A, issueId: ISSUE }).success,
    ).toBe(false);
    expect(
      changeIssueStatusSchema.parse({ orgId: ORG_A, issueId: ISSUE, status: "done" })
        .status,
    ).toBe("done");
  });

  it("allows unassignment with an explicit null", () => {
    expect(
      assignIssueSchema.parse({ orgId: ORG_A, issueId: ISSUE, assigneeId: null })
        .assigneeId,
    ).toBeNull();
    expect(
      assignIssueSchema.parse({ orgId: ORG_A, issueId: ISSUE, assigneeId: ALICE })
        .assigneeId,
    ).toBe(ALICE);
    expect(assignIssueSchema.safeParse({ orgId: ORG_A, issueId: ISSUE }).success).toBe(
      false,
    );
  });

  it("carries pagination and archive scope on the filter schema", () => {
    const parsed = issueFilterSchema.parse({ orgId: ORG_A });
    expect(parsed.limit).toBe(25);
    expect(parsed.includeArchived).toBeUndefined();

    expect(
      issueFilterSchema.parse({ orgId: ORG_A, limit: 50, includeArchived: true }),
    ).toMatchObject({ limit: 50, includeArchived: true });
    expect(issueFilterSchema.safeParse({ orgId: ORG_A, limit: 101 }).success).toBe(false);
  });

  it("requires a non-negative board index on move", () => {
    expect(
      moveIssueSchema.safeParse({
        orgId: ORG_A,
        issueId: ISSUE,
        toStatus: "todo",
        toIndex: -1,
      }).success,
    ).toBe(false);
    expect(
      moveIssueSchema.safeParse({
        orgId: ORG_A,
        issueId: ISSUE,
        toStatus: "todo",
        toIndex: 0,
      }).success,
    ).toBe(true);
  });

  it("needs only the org and issue to archive", () => {
    expect(archiveIssueSchema.parse({ orgId: ORG_A, issueId: ISSUE })).toEqual({
      orgId: ORG_A,
      issueId: ISSUE,
    });
  });
});
/**
 * Every query filters by `orgId` and by `archived_at`.
 *
 * Owner C implements `@/server/repositories/issue-repository`. Seed with
 * `seedTwoTenants()` from `tests/helpers/db.ts` so the negative case is a real
 * row in the other tenant.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as permissions from "@/lib/permissions";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("northwind-issues");
  acme = await createTenant("acme-issues");
});

afterAll(() => {
  cleanup();
});

/** Inserts one issue directly through the repository, bypassing the service. */
async function insertIssue(
  tenant: Tenant,
  overrides: Partial<{ title: string; assigneeId: (typeof tenant.userIds)["member"] | null }> = {},
) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, tenant.project.id, overrides),
    tenant.userIds.owner,
    number,
  );
}

describe("repositories/issue-repository", () => {
  it("excludes another tenant's issues from every list query", async () => {
    const northIssue = await insertIssue(north, { title: "North only" });
    await insertIssue(acme, { title: "Acme only" });

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((issue) => issue.id)).toContain(northIssue.id);
    expect(page.items.every((issue) => issue.orgId === north.org.id)).toBe(true);
  });

  it("returns null for an id that belongs to another tenant", async () => {
    const issue = await insertIssue(north, { title: "Northwind private" });

    await expect(issueRepo.findIssueById(acme.org.id, issue.id)).resolves.toBeNull();
    await expect(
      issueRepo.findIssueById(north.org.id, issue.id),
    ).resolves.not.toBeNull();
  });

  it("hides archived issues unless includeArchived is set", async () => {
    const issue = await insertIssue(north, { title: "To be archived" });
    await issueRepo.archiveIssue(north.org.id, issue.id);

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
    });

    expect(page.items.map((row) => row.id)).not.toContain(issue.id);
  });

  it("returns archived issues when the scope asks for them", async () => {
    const issue = await insertIssue(north, { title: "Also archived" });
    await issueRepo.archiveIssue(north.org.id, issue.id);

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
      includeArchived: true,
    });

    expect(page.items.map((row) => row.id)).toContain(issue.id);
  });

  it("applies status, priority, assignee and label filters together", async () => {
    const label = await labelRepo.insertLabel({
      orgId: north.org.id,
      name: "urgent-bug",
      color: "#ef4444",
      description: null,
    });

    const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    const matching = await issueRepo.insertIssue(
      {
        ...issueInput(north.org.id, north.project.id, {
          title: "Matches every filter",
          assigneeId: north.userIds.member,
        }),
        status: "in_progress",
        priority: "urgent",
        labelIds: [label.id],
      },
      north.userIds.owner,
      number,
    );

    // A near-identical issue that only differs by status must not match.
    const otherNumber = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
    await issueRepo.insertIssue(
      {
        ...issueInput(north.org.id, north.project.id, {
          title: "Wrong status",
          assigneeId: north.userIds.member,
        }),
        status: "backlog",
        priority: "urgent",
        labelIds: [label.id],
      },
      north.userIds.owner,
      otherNumber,
    );

    const page = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
      status: ["in_progress"],
      priority: ["urgent"],
      assigneeId: north.userIds.member,
      labelIds: [label.id],
    });

    expect(page.items.map((row) => row.id)).toEqual([matching.id]);
  });

  it("pages with a cursor and reports the total", async () => {
    const org = await createTenant("pager-issues");
    for (const title of ["First", "Second", "Third"]) {
      const number = await issueRepo.nextIssueNumber(org.org.id, org.project.id);
      await issueRepo.insertIssue(
        issueInput(org.org.id, org.project.id, { title }),
        org.userIds.owner,
        number,
      );
    }

    const firstPage = await issueRepo.listIssues({
      orgId: org.org.id,
      limit: 2,
      cursor: null,
    });

    expect(firstPage.items).toHaveLength(2);
    expect(firstPage.total).toBe(3);
    expect(firstPage.nextCursor).not.toBeNull();

    const secondPage = await issueRepo.listIssues({
      orgId: org.org.id,
      limit: 2,
      cursor: firstPage.nextCursor,
    });

    expect(secondPage.items).toHaveLength(1);
    expect(secondPage.nextCursor).toBeNull();

    const seenIds = new Set([
      ...firstPage.items.map((row) => row.id),
      ...secondPage.items.map((row) => row.id),
    ]);
    expect(seenIds.size).toBe(3);
  });

  it("performs no authorization of its own", async () => {
    const canSpy = vi.spyOn(permissions, "can");
    const assertCanSpy = vi.spyOn(permissions, "assertCan");

    const issue = await insertIssue(north, { title: "No auth check here" });
    await issueRepo.findIssueById(north.org.id, issue.id);
    await issueRepo.listIssues({ orgId: north.org.id, limit: 10, cursor: null });

    expect(canSpy).not.toHaveBeenCalled();
    expect(assertCanSpy).not.toHaveBeenCalled();

    canSpy.mockRestore();
    assertCanSpy.mockRestore();
  });
});

