        flags={ALL_FLAGS}
        projects={[]}
        pathname="/acme"
      />,
    );

    const issuesLink = screen.getByRole("link", { name: "Issues" });
    const parentItem = issuesLink.closest("li");
    expect(parentItem).not.toBeNull();

