  // With the kanban_board flag off, the Board child link is absent.
  it("omits a nav item whose flag is off in the snapshot", () => {
    const org = makeOrganization();
    const actor = makeActor({ role: "owner", orgId: org.id });

    render(
      <AppSidebar
        org={org}
        actor={actor}
        flags={NO_FLAGS}
        projects={[]}
        pathname="/acme"
