 * archived ones alongside for `includeArchived: true`, archived ones alone
 * for `"only"`.
 */
function archivePredicates(
  includeArchived: IssueFilterInput["includeArchived"],
): readonly (SQL | undefined)[] {
  const archivedOnly = includeArchived === ARCHIVED_ONLY;
  // An archived-only listing has to lift the live-rows predicate as well.
  const scope: ArchiveScope = shouldFilterArchived({
    includeArchived: archivedOnly || includeArchived === true,
  })
    ? {}
