 * `me` names the acting user, and a repository has no actor: the service
 * resolves it before a filter gets here. Comparing the column with the
 * literal would quietly match nothing, so an unresolved `me` is an error.
 */
function resolvedUserId(
  field: "assigneeId" | "authorId",
  value: UserId | typeof ME_TOKEN,
): UserId {
  if (value === ME_TOKEN) {
    throw new Error(
      `Issue filter ${field} "${ME_TOKEN}" must be resolved against the acting user before it reaches the repository.`,
