function dueBeforePredicate(dueBefore: string): SQL {
  const bound = dueBeforeBound(dueBefore);
  if (bound === null) {
    throw new RangeError(
      `Issue filter dueBefore "${dueBefore}" is neither a calendar date nor an ISO-8601 timestamp.`,
