import { issueFilterToParams, parseIssueFilterParams, readableSearchParams } from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { orgNavPath } from "@/lib/url";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let t: Tenant;
const ids: Record<string, string> = {};
let l1: string, l2: string;

async function add(title: string, o: Record<string, unknown> = {}) {
  const number = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  const issue = await issueRepo.insertIssue(
    { ...issueInput(t.org.id, t.project.id, { title }), ...o } as never,
    (o.authorId as never) ?? t.userIds.owner,
    number,
  );
  ids[title] = issue.id;
  return issue;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("scratch");
  l1 = (await labelRepo.insertLabel({ orgId: t.org.id, name: "bug", color: "#ef4444", description: null })).id;
  l2 = (await labelRepo.insertLabel({ orgId: t.org.id, name: "regression", color: "#ef4444", description: null })).id;
  await add("mine-open", { assigneeId: t.userIds.member, status: "todo", labelIds: [l1, l2], dueAt: "2026-03-15T00:00:00.000Z" });
  await add("mine-done", { assigneeId: t.userIds.member, status: "done", labelIds: [l1], dueAt: "2026-03-15T23:59:59Z" });
  await add("unassigned", { status: "in_review", labelIds: [l2], dueAt: "2026-03-16T00:00:00.000Z" });
  await add("other", { assigneeId: t.userIds.admin, status: "canceled", dueAt: "2026-03-14T10:00:00.000Z" });
  await add("nodue", { assigneeId: t.userIds.admin, status: "backlog" });
  const a = await add("archived", { assigneeId: t.userIds.member, status: "todo", labelIds: [l1, l2] });
  await issueRepo.archiveIssue(t.org.id, a.id as never);
});
afterAll(() => cleanup());

async function viaUrl(query: string, actor = t.actors.member) {
  const filter = parseIssueFilterParams(new URLSearchParams(query));
  const input = issueFilterSchema.parse({ ...filter, orgId: t.org.id, limit: 100 });
  const page = await issueService.listIssues(actor, input);
  expect(page.total).toBe(page.items.length);
  return page.items.map((i) => i.title).sort();
}

describe("adr 0009 scratch", () => {
  it("me", async () => {
    expect(await viaUrl("assignee=me")).toEqual(["mine-done", "mine-open"]);
    expect(await viaUrl("assignee=me", t.actors.admin)).toEqual(["nodue", "other"]);
    expect(await viaUrl("author=me", t.actors.owner)).toHaveLength(5);
    expect(await viaUrl("author=me")).toEqual([]);
    const direct = await issueService.listIssues(t.actors.member, issueFilterSchema.parse({ orgId: t.org.id, assigneeId: "me" }));
    expect(direct.total).toBe(2);
    await expect(issueRepo.listIssues({ orgId: t.org.id, assigneeId: "me", limit: 10 })).rejects.toThrow(/resolved/);
  });
  it("unassigned", async () => {
    expect(await viaUrl("assignee=none")).toEqual(["unassigned"]);
    expect(issueFilterSchema.parse({ orgId: t.org.id, assigneeId: "none" }).assigneeId).toBeNull();
    expect((await issueRepo.listIssues({ orgId: t.org.id, assigneeId: null, limit: 10 })).total).toBe(1);
  });
  it("labels all-of", async () => {
    expect(await viaUrl(`label=${l1},${l2}`)).toEqual(["mine-open"]);
    expect(await viaUrl(`label=${l1},${l2},${l1}`)).toEqual(["mine-open"]);
    expect(await viaUrl(`label=${l1}`)).toEqual(["mine-done", "mine-open"]);
    expect(await viaUrl(`label=${l1},${l2}&archived=1`)).toEqual(["archived", "mine-open"]);
    const p = await issueRepo.listIssues({ orgId: t.org.id, labelIds: [l1, l2] as never, limit: 1 });
    expect(p.total).toBe(1);
  });
  it("due before", async () => {
    expect(await viaUrl("due_before=2026-03-15")).toEqual(["mine-done", "mine-open", "other"]);
    expect(await viaUrl("due_before=2026-03-15T00:00:00.000Z")).toEqual(["other"]);
    expect(await viaUrl("due_before=2026-03-15T00:00:00Z")).toEqual(["other"]);
    expect(await viaUrl("due_before=2026-03-15T23:59:59.500Z")).toEqual(["mine-done", "mine-open", "other"]);
    expect(await viaUrl("due_before=2026-03-14")).toEqual(["other"]);
    expect(await viaUrl("due_before=2026-03-13")).toEqual([]);
    expect(parseIssueFilterParams(new URLSearchParams("due_before=garbage"))).toEqual({});
    expect(parseIssueFilterParams(new URLSearchParams("due_before=2026-02-30"))).toEqual({});
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-02-30" }).success).toBe(false);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-03-15" }).success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "15/03/2026" }).success).toBe(false);
    expect((await issueRepo.listIssues({ orgId: t.org.id, dueBefore: "2026-03-15" as never, limit: 10 })).total).toBe(3);
  });
  it("status groups", async () => {
    expect(parseIssueFilterParams(new URLSearchParams("status=open")).status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    expect(parseIssueFilterParams(new URLSearchParams("status=closed,todo,bogus,todo")).status).toEqual(["done", "canceled", "todo"]);
    expect(await viaUrl("status=open")).toEqual(["mine-open", "nodue", "unassigned"]);
    expect(await viaUrl("status=closed")).toEqual(["mine-done", "other"]);
    expect(await viaUrl("status=closed,todo")).toEqual(["mine-done", "mine-open", "other"]);
    const direct = issueFilterSchema.parse({ orgId: t.org.id, status: ["open"] });
    expect((await issueService.listIssues(t.actors.owner, direct)).total).toBe(3);
    expect((await issueRepo.listIssues({ orgId: t.org.id, status: ["closed", "done"], limit: 10 })).total).toBe(2);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["shipped"] }).success).toBe(false);
  });
  it("archived", async () => {
    expect(await viaUrl("archived=only")).toEqual(["archived"]);
    expect(await viaUrl("archived=1")).toHaveLength(6);
    expect(await viaUrl("")).toHaveLength(5);
    expect(issueFilterToParams(parseIssueFilterParams(new URLSearchParams("archived=only")))).toEqual({ archived: "only" });
    expect(await viaUrl("archived=only&assignee=me&status=open")).toEqual(["archived"]);
  });
  it("misc", () => {
    expect(orgNavPath("acme", "issues?assignee=me")).toBe("/acme/issues?assignee=me");
    expect(orgNavPath("acme", "")).toBe("/acme");
    expect(orgNavPath("acme", "board")).toBe("/acme/board");
    expect(parseIssueFilterParams(readableSearchParams({ status: ["todo", "closed"], assignee: "me", q: "x" }))).toEqual({
      status: ["todo", "done", "canceled"], assigneeId: "me", query: "x",
    });
    expect(parseIssueFilterParams(new URLSearchParams("status=todo&status=done")).status).toEqual(["todo", "done"]);
  });
});
